{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { parseFormula, depsOf } from './formula.js'
import { evaluateAll, formatValue } from './eval.js'

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'values' && args[0] !== 'deps')) fail('error: usage: cli.js values|deps')
const mode = args[0]

let cells
try {
  cells = parseSheet(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.sheetError) fail(e.message)
  throw e
}

for (const cell of cells) {
  cell.ast = cell.content.startsWith('=') ? parseFormula(cell.content.slice(1)) : null
}

let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const cell of cells) out += `${cell.name}=${formatValue(vals.get(cell.key))}\n`
} else {
  for (const cell of cells) {
    out += `${cell.name}:`
    if (cell.ast && cell.ast.t !== 'bad') for (const n of depsOf(cell.ast)) out += ` ${n}`
    out += '\n'
  }
}
process.stdout.write(out)
"}

{"file_path":"src/sheet.js","content":"export function colIndex(letters) {
  letters = letters.toUpperCase()
  return letters.length === 1
    ? letters.charCodeAt(0) - 64
    : (letters.charCodeAt(0) - 64) * 26 + letters.charCodeAt(1) - 64
}

export function colName(i) {
  return i <= 26 ? String.fromCharCode(64 + i) : String.fromCharCode(64 + Math.floor((i - 1) / 26)) + String.fromCharCode(65 + ((i - 1) % 26))
}

// Returns {c, r, key, name} or null when the word is not an addressable cell.
export function parseAddress(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const r = Number(m[2])
  if (r < 1) return null
  const c = colIndex(m[1])
  return { c, r, key: c * 1000 + r, name: colName(c) + r }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const word = m[1]
    const addr = parseAddress(word)
    const err = (msg) => Object.assign(new Error(`error: line ${i + 1}: ${msg}`), { sheetError: true })
    if (!addr) throw err(`invalid cell address ${word}`)
    if (seen.has(addr.key)) throw err(`cell ${addr.name} is declared twice`)
    seen.add(addr.key)
    cells.push({ ...addr, content: m[2] })
  })
  cells.sort((a, b) => a.key - b.key)
  return cells
}
"}

{"file_path":"src/formula.js","content":"import { parseAddress } from './sheet.js'

const BAD = { t: 'bad' }

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>^*/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return BAD
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw BAD }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) fail()
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { t: 'paren', e }
    }
    if (tk.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            const a = cmp()
            if (a.t === 'range') a.direct = true
            args.push(a)
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word') fail()
        p++
        return { t: 'range', a: tk.v, b: t2.v, direct: false }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', w: tk.v }
    }
    fail()
  }

  let ast
  try {
    ast = cmp()
    if (p < toks.length) return BAD
  } catch (e) {
    if (e === BAD) return BAD
    throw e
  }
  let misplaced = false
  walk(ast, (n) => { if (n.t === 'range' && !n.direct) misplaced = true })
  if (misplaced) ast.misplaced = true
  return misplaced ? { t: 'misplaced', e: ast } : ast
}

function children(n) {
  switch (n.t) {
    case 'bin': return [n.l, n.r]
    case 'neg': case 'paren': case 'misplaced': return [n.e]
    case 'call': return n.args
    default: return []
  }
}

function walk(n, f) {
  f(n)
  for (const c of children(n)) walk(c, f)
}

export function depsOf(ast) {
  const keys = new Map()
  walk(ast, (n) => {
    if (n.t === 'ref') {
      const a = parseAddress(n.w)
      if (a) keys.set(a.key, a.name)
    } else if (n.t === 'range') {
      const a = parseAddress(n.a)
      const b = parseAddress(n.b)
      if (a && b) {
        for (let c = Math.min(a.c, b.c); c <= Math.max(a.c, b.c); c++) {
          for (let r = Math.min(a.r, b.r); r <= Math.max(a.r, b.r); r++) {
            const x = parseAddress(colLetters(c) + r)
            keys.set(x.key, x.name)
          }
        }
      } else {
        for (const x of [a, b]) if (x) keys.set(x.key, x.name)
      }
    }
  })
  return [...keys.entries()].sort((x, y) => x[0] - y[0]).map((e) => e[1])
}

import { colName } from './sheet.js'
function colLetters(c) { return colName(c) }
"}

