        if (x.k === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': {
        const l = ev(n.l)
        if (l.k === 'err') return l
        const r = ev(n.r)
        if (r.k === 'err') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
