{"file_path":"src/sheet.js","content":"export function colIndex(letters) {
  letters = letters.toUpperCase()
  return letters.length === 1
    ? letters.charCodeAt(0) - 64
    : (letters.charCodeAt(0) - 64) * 26 + letters.charCodeAt(1) - 64
}

export function colName(i) {
  return i <= 26 ? String.fromCharCode(64 + i) : String.fromCharCode(64 + Math.floor((i - 1) / 26)) + String.fromCharCode(65 + ((i - 1) % 26))
}

// Returns {c, r, key, name} or null when the word is not an addressable cell.
export function parseAddress(word) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(word)
  if (!m) return null
  const r = Number(m[2])
  if (r < 1) return null
  const c = colIndex(m[1])
  return { c, r, key: c * 1000 + r, name: colName(c) + r }
}

export function parseSheet(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const seen = new Set()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const word = m[1]
    const addr = parseAddress(word)
    const err = (msg) => Object.assign(new Error(`error: line ${i + 1}: ${msg}`), { sheetError: true })
    if (!addr) throw err(`invalid cell address ${word}`)
    if (seen.has(addr.key)) throw err(`cell ${addr.name} is declared twice`)
    seen.add(addr.key)
    cells.push({ ...addr, content: m[2] })
  })
  cells.sort((a, b) => a.key - b.key)
  return cells
}
"}

{"file_path":"src/formula.js","content":"import { parseAddress } from './sheet.js'

const BAD = { t: 'bad' }

function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>^*/+\-(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return BAD
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const fail = () => { throw BAD }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'neg', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const tk = peek()
    if (!tk) fail()
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return { t: 'paren', e }
    }
    if (tk.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) p++
        else {
          for (;;) {
            const a = cmp()
            if (a.t === 'range') a.direct = true
            args.push(a)
            if (isOp(',')) { p++; continue }
            if (isOp(')')) { p++; break }
            fail()
          }
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word') fail()
        p++
        return { t: 'range', a: tk.v, b: t2.v, direct: false }
      }
      const up = tk.v.toUpperCase()
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', w: tk.v }
    }
    fail()
  }

  let ast
  try {
    ast = cmp()
    if (p < toks.length) return BAD
  } catch (e) {
    if (e === BAD) return BAD
    throw e
  }
  let misplaced = false
  walk(ast, (n) => { if (n.t === 'range' && !n.direct) misplaced = true })
  if (misplaced) ast.misplaced = true
  return misplaced ? { t: 'misplaced', e: ast } : ast
}

function children(n) {
  switch (n.t) {
    case 'bin': return [n.l, n.r]
    case 'neg': case 'paren': case 'misplaced': return [n.e]
    case 'call': return n.args
    default: return []
  }
}

function walk(n, f) {
  f(n)
  for (const c of children(n)) walk(c, f)
}

export function depsOf(ast) {
  const keys = new Map()
  walk(ast, (n) => {
    if (n.t === 'ref') {
      const a = parseAddress(n.w)
      if (a) keys.set(a.key, a.name)
    } else if (n.t === 'range') {
      const a = parseAddress(n.a)
      const b = parseAddress(n.b)
      if (a && b) {
        for (let c = Math.min(a.c, b.c); c <= Math.max(a.c, b.c); c++) {
          for (let r = Math.min(a.r, b.r); r <= Math.max(a.r, b.r); r++) {
            const x = parseAddress(colLetters(c) + r)
            keys.set(x.key, x.name)
          }
        }
      } else {
        for (const x of [a, b]) if (x) keys.set(x.key, x.name)
      }
    }
  })
  return [...keys.entries()].sort((x, y) => x[0] - y[0]).map((e) => e[1])
}

import { colName } from './sheet.js'
function colLetters(c) { return colName(c) }
"}

{"file_path":"src/eval.js","content":"import { parseAddress } from './sheet.js'

const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ k: 'err', e })
const num = (v) => (Number.isFinite(v) ? { k: 'num', v } : err('#DIV/0!'))

export function formatValue(v) {
  switch (v.k) {
    case 'num': return String(Number(v.v.toPrecision(10)))
    case 'err': return v.e
    case 'bool': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}

function literal(content) {
  if (content === '') return { k: 'num', v: 0 }
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return { k: 'num', v: Number(content) }
  if (ERRORS.includes(content)) return err(content)
  return { k: 'text', v: content }
}

function toNum(v) {
  if (v.k === 'num') return v
  if (v.k === 'bool') return { k: 'num', v: v.v ? 1 : 0 }
  return err('#VALUE!')
}

const rank = { num: 0, text: 1, bool: 2 }
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 'text') {
    const x = Array.from(a.v), y = Array.from(b.v)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  const x = Number(a.v), y = Number(b.v)
  return x < y ? -1 : x > y ? 1 : 0
}

export function evaluateAll(cells) {
  const byKey = new Map(cells.map((c) => [c.key, c]))
  const memo = new Map()
  const busy = new Set()

  function cellValue(key) {
    if (memo.has(key)) return memo.get(key)
    const cell = byKey.get(key)
    if (!cell) return { k: 'num', v: 0 }
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    const v = cell.ast ? ev(cell.ast) : literal(cell.content)
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function refValue(w) {
    const a = parseAddress(w)
    return a ? cellValue(a.key) : err('#REF!')
  }

  // Expands an argument to a list of values (a range gives all its cells).
  function argValues(n) {
    if (n.t !== 'range') return [ev(n)]
    const a = parseAddress(n.a), b = parseAddress(n.b)
    if (!a || !b) return [err('#REF!')]
    const out = []
    for (let c = Math.min(a.c, b.c); c <= Math.max(a.c, b.c); c++) {
      for (let r = Math.min(a.r, b.r); r <= Math.max(a.r, b.r); r++) out.push(cellValue(c * 1000 + r))
    }
    return out
  }

  function call(n) {
    const name = n.name, args = n.args
    const agg = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG']
    if (agg.includes(name)) {
      if (args.length < 1) return err('#ERR!')
      const vals = args.flatMap(argValues)
      const bad = vals.find((v) => v.k === 'err')
      if (bad) return bad
      if (name === 'COUNT') return { k: 'num', v: vals.filter((v) => v.k === 'num').length }
      const nums = []
      for (const v of vals) {
        const x = toNum(v)
        if (x.k === 'err') return x
        nums.push(x.v)
      }
      if (name === 'SUM') return num(nums.reduce((s, x) => s + x, 0))
      if (name === 'AVG') {
        const t = nums.reduce((s, x) => s + x, 0)
        return num(t / nums.length)
      }
      return num(name === 'MIN' ? Math.min(...nums) : Math.max(...nums))
    }
    if (name === 'ABS') {
      if (args.length !== 1) return err('#ERR!')
      const vals = argValues(args[0])
      if (vals.length !== 1) return vals.find((v) => v.k === 'err') || err('#ERR!')
      const x = toNum(vals[0])
      return vals[0].k === 'err' ? vals[0] : x.k === 'err' ? x : num(Math.abs(x.v))
    }
    if (name === 'IF') {
      if (args.length !== 3) return err('#ERR!')
      const cv = argValues(args[0])
      if (cv.length !== 1) return cv.find((v) => v.k === 'err') || err('#ERR!')
      const c = cv[0]
      if (c.k === 'err') return c
      if (c.k === 'text') return err('#VALUE!')
      const t = c.k === 'bool' ? c.v : c.v !== 0
      const pick = args[t ? 1 : 2]
      const r = argValues(pick)
      return r.length === 1 ? r[0] : r.find((v) => v.k === 'err') || err('#ERR!')
    }
    return err('#NAME?')
  }

  function ev(n) {
    switch (n.t) {
      case 'bad': return err('#ERR!')
      case 'misplaced': return err('#ERR!')
      case 'num': return { k: 'num', v: n.v }
      case 'bool': return { k: 'bool', v: n.v }
      case 'paren': return ev(n.e)
      case 'ref': return refValue(n.w)
      case 'range': return err('#ERR!')
      case 'call': return call(n)
      case 'neg': {
        const v = ev(n.e)
        if (v.k === 'err') return v
        const x = toNum(v)
        if (x.k === 'err') return x
        return num(n.op === '-' ? -x.v : x.v)
      }
      case 'bin': {
        const l = ev(n.l)
        if (l.k === 'err') return l
        const r = ev(n.r)
        if (r.k === 'err') return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const d = compare(l, r)
          const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
          return { k: 'bool', v: res }
        }
        const x = toNum(l)
        if (x.k === 'err') return x
        const y = toNum(r)
        if (y.k === 'err') return y
        switch (n.op) {
          case '+': return num(x.v + y.v)
          case '-': return num(x.v - y.v)
          case '*': return num(x.v * y.v)
          case '/': return y.v === 0 ? err('#DIV/0!') : num(x.v / y.v)
          default: return num(Math.pow(x.v, y.v))
        }
      }
    }
    return err('#ERR!')
  }

  const result = new Map()
  for (const c of cells) result.set(c.key, cellValue(c.key))
  return result
}
"}

